settings.markdownCss:
.mainDiv {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    padding: 0;
    gap: 15px;
    /*overflow-y: auto;*/
}

.imageBlock {
    /*padding: 20px;*/
    /*height: 150px;*/
    width: 100% !important;
    height: auto;
    display: flex;
    align-items: center;
    justify-content: center;
}

.infoBlock {
    width: 100%;
    display: flex;
    flex-direction: column;
    /*padding: 0;*/
}

.row {
    width: 100%;
    display: flex;
    justify-content: start;
    align-items: center;
    padding: 2px 0px;
    gap: 20px;
}

.childRow {
    gap: 5px;
}

.between {
    justify-content: space-between;
}

.key {
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
    text-align: left;
    color: #344054;
}

.descriptionBlock {
    height: auto;
    color: #344054;
    display: flex;
    flex-direction: column;
    overflow: auto;
}

.deviceBlock {
    height: auto;
    color: #344054;
    display: flex;
    flex-direction: column;
}

.title {
    color: #0C111D;
    font-size: 24px;
    font-weight: 600;
    line-height: 32px;
    text-align: left;
}

.text {
    padding: 10px 0px;    
}

.customB {
    font-size: 16px;
    font-weight: 600;
    line-height: 24px;
    letter-spacing: 0.01em;
    text-align: left;
    color: #344054;
}

.inactive {
    color: #475467;
    background-color: #EAECF0;
    border-radius: 4px;
    padding: 5px;
    font-size: 12px;
    font-weight: 600;
    line-height: 16px;
    text-align: left;   
}

.active {
    color: #026AA2;
    background-color: #E0F2FE;
    border-radius: 4px;
    padding: 5px;
    font-size: 12px;
    font-weight: 600;
    line-height: 16px;
    text-align: left;
}

.value {
    color: #0C111D;
    font-size: 14px;
    font-weight: 500;
    line-height: 20px;
    text-align: left;
}

.bb {
    padding-bottom: 10px;
    border-bottom: 1px solid #D0D5DD;
}
